mapper.select:
select t.id, t.app_id as appId, t.platform as platform, t.channel as channel, t.name as name, t.code, t.desc, t.url, t.is_force_update as isForceUpdate, t.is_open_tip as isOpenTip, t.create_time as createTime, t.update_time as updateTime, t.in_app_update as inAppUpdate from c_app_versions t where t.status = 0
and t.app_id = #{appId}
and t.platform = #{platform}
and t.channel = #{channel}
and t.lang = #{lang}
order by t.id desc limit 1
